def two_sum_sorted(nums, target):
    kiri, kanan = 0, len(nums) - 1
    while kiri < kanan:
        jumlah = nums[kiri] + nums[kanan]
        if jumlah == target:
            return [kiri, kanan]
        if jumlah < target:
            kiri += 1
        else:
            kanan -= 1
    return []
